{
  "shared_conditions": [
    "The speed assessment concerns a cold engine cranking at 90 RPM.",
    "The voltage-drop assessment concerns a 0.30 V starter negative-cable reading from STE/ICE-R Test 69 during cranking."
  ],
  "statements": [
    {
      "statement": "For a cold HMMWV (M998-series) engine, the manual is said to typically recommend a minimum cranking speed of 60–80 RPM for proper starting.",
      "answer_quote": "The manual typically recommends a minimum cranking speed of 60–80 RPM for proper engine start"
    },
    {
      "statement": "For the cold engine cranking at 90 RPM, the speed is said to be acceptable and to meet or exceed manual guidance.",
      "answer_quote": "90 RPM is acceptable and meets or exceeds guidance"
    },
    {
      "statement": "For the HMMWV (M998-series) starter negative-cable assessment during cranking, the manual is said to generally treat a drop of more than 0.20 V at the starter terminal as indicating a negative-cable or connection problem.",
      "answer_quote": "The manual generally specifies that a voltage drop of more than 0.20 V at the starter terminal during cranking indicates a problem with the negative cable or connection"
    },
    {
      "statement": "For the 0.30 V starter negative-cable reading during cranking, the drop is said to be excessive and above the stated manual threshold.",
      "answer_quote": "A drop of 0.30 V exceeds this threshold"
    },
    {
      "statement": "For the 0.30 V starter negative-cable reading during cranking, the possible cable or connection problem is suggested to involve poor conductivity or corrosion.",
      "answer_quote": "suggesting poor conductivity or corrosion"
    },
    {
      "statement": "For the 0.30 V starter negative-cable reading during cranking, the answer says the potential issue requires inspection and repair.",
      "answer_quote": "indicates a potential issue requiring inspection and repair"
    }
  ],
  "excluded_metadata": [
    "The answer says the provided reference contains no manual excerpts.",
    "The answer says guidance from the named manual cannot be cited.",
    "The answer describes its basis as general knowledge of HMMWV (M998-series) maintenance."
  ]
}

